-- Ramsay AI-Supervisor — Lakebase seed (exact mirror of UK-South chat history: 8 conversations, 22 messages, 11 traces).
-- Idempotent: tables created if absent (mirrors app server/db.py init_db), then rows upserted.

CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, title TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT, role TEXT, content TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS traces (id TEXT PRIMARY KEY, conversation_id TEXT, turn_id TEXT, events JSONB, created_at TIMESTAMPTZ DEFAULT now());


