INSERT INTO traces (id,conversation_id,turn_id,events,created_at) VALUES ('32f29e93-c46b-474c-a406-608003c35435','ce29e341-1eb3-4277-ad02-c8a7e38658e2','e0318c01-2253-464b-816b-73999c08348e','[{"stage": "decompose_start"}, {"stage": "decompose", "subquestions": ["What is the meaning of RTT breach rate?"]}, {"stage": "route", "routes": [{"agent": "throughput_flow", "question": "What is the meaning of RTT breach rate?", "rationale": "fallback single route", "agentLabel": "Throughput & Flow"}]}, {"count": 1, "stage": "agents_start"}, {"agent": "throughput_flow", "stage": "agent_call_start", "question": "What is the meaning of RTT breach rate?", "agentLabel": "Throughput & Flow"}, {"sql": null, "rows": [], "agent": "throughput_flow", "error": null, "stage": "agent_call_done", "answer": "The RTT breach rate is the percentage of patients whose referral-to-treatment (RTT) time exceeds 18 weeks, which is the NHS target. It measures how many patients waited longer than the standard for their first definitive treatment after referral. This rate is calculated as the number of RTT breaches divided by the total number of referrals, typically expressed as a percentage.", "columns": [], "question": "What is the meaning of RTT breach rate?", "rowCount": 0, "thoughts": [], "latencyMs": 5352, "agentLabel": "Throughput & Flow", "description": null}, {"stage": "synthesize_start"}, {"chart": null, "stage": "synthesize", "sources": ["Throughput & Flow"]}, {"chart": null, "stage": "final", "answer": "The RTT breach rate is the percentage of patients whose referral\u2011to\u2011treatment time exceeds the NHS 18\u2011week target, calculated as the number of breaches divided by the total number of referrals.  \n\n- It measures how many patients wait longer than the standard for their first definitive treatment after referral.  \n\n*Sources: Throughput & Flow agent*"}, {"stage": "turn_record", "record": {"question": "What is the meaning of RTT breach rate?", "per_agent": [{"sql": null, "agent": "throughput_flow", "error": null, "row_count": 0, "agentLabel": "Throughput & Flow", "latency_ms": 5352, "row_preview": [], "sub_question": "What is the meaning of RTT breach rate?"}], "chart_spec": null, "agents_called": ["Throughput & Flow"], "guardrail_events": [], "agent_keys_called": ["throughput_flow"], "final_answer_text": "The RTT breach rate is the percentage of patients whose referral\u2011to\u2011treatment time exceeds the NHS 18\u2011week target, calculated as the number of breaches divided by the total number of referrals.  \n\n- It measures how many patients wait longer than the standard for their first definitive treatment after referral.  \n\n*Sources: Throughput & Flow agent*"}}, {"stage": "done", "demoMode": false, "conversationId": "ce29e341-1eb3-4277-ad02-c8a7e38658e2"}]'::jsonb,'2026-08-23 07:31:53.883193+00:00') ON CONFLICT (id) DO UPDATE SET conversation_id=EXCLUDED.conversation_id,turn_id=EXCLUDED.turn_id,events=EXCLUDED.events,created_at=EXCLUDED.created_at;
